mapper.select:
SELECT r.record_id, r.emp_id, r.att_date, r.att_start_time, r.att_end_time,
       r.att_status, r.is_supplement, r.att_type, r.att_sub_type, r.apply_id, r.day,
       r.create_time, r.update_time,
       COALESCE(e.emp_code, '') AS emp_code,
       COALESCE(e.emp_name, '') AS emp_name
FROM hr_att_record r
LEFT JOIN sys_emp e ON r.emp_id = e.emp_id
WHERE 1=1

    AND r.emp_id = #{empId}


    AND r.att_date = #{attDate}


    AND r.att_date >= #{startDate}


    AND r.att_date <= #{endDate}


    AND r.att_status = #{attStatus}


    AND r.att_type = #{attType}


    AND r.att_sub_type = #{attSubType}

ORDER BY r.att_date DESC, r.att_start_time DESC

mapper.update:
UPDATE hr_att_record
att_start_time = #{attStartTime}, att_end_time = #{attEndTime}, att_status = #{attStatus}, is_supplement = #{isSupplement}, att_type = #{attType}, att_sub_type = #{attSubType}, apply_id = #{applyId}, day = #{day},
WHERE record_id = #{recordId}
